/* Grab the real payload:
   – If the Webhook put it under body, use that.
   – Otherwise (future proof) fall back to the top level.            */
const payload = $json.body ?? $json;

return [{
  json: {
    barcode:        String(payload.barcode || ""),
    product_name:   payload.product_name || "",
    user_profile:   payload.user_profile || {},
    // keep the photo if Streamlit sent one
    label_photo:    payload.label_photo        // may be undefined
  }
}];

let input = $json;
let isOpenFoodFacts = !!input.product;

// Normalize function
function normalizeOpenFoodFacts(api) {
  const p = api.product || {};
  const nutriments = p.nutriments || {};

  return {
    product_name: p.product_name_nl || p.product_name || "",
    barcode: api.code || "",
    category: (p.categories_tags || [])[0] || "",
    nutriscore: p.nutrition_grade_fr || p.nutriscore_grade || "",
    image_url: p.image_url || p.selected_images?.front?.display?.nl || "",
    image_ingredients_url: p.image_ingredients_url || p.selected_images?.ingredients?.display?.nl || "",
    image_nutrition_url: p.image_nutrition_url || p.selected_images?.nutrition?.display?.nl || "",
    ingredients_text: p.ingredients_text_nl || p.ingredients_text || "",
    ingredients: (p.ingredients || []).map(i => ({ id: i.id || i.text || "" })),
    allergy_info: (p.allergens_from_ingredients || "").replace(/en:/g, "").trim(),
    nutrition_per_100g: {
      energy_kcal_100g: parseFloat(nutriments["energy-kcal_100g"]) || undefined,
      energy_kj_100g: parseFloat(nutriments["energy-kj_100g"]) || undefined,
      fat_100g: parseFloat(nutriments.fat_100g) || undefined,
      saturated_fat_100g: parseFloat(nutriments["saturated-fat_100g"]) || undefined,
      carbohydrates_100g: parseFloat(nutriments.carbohydrates_100g) || undefined,
      sugars_100g: parseFloat(nutriments.sugars_100g) || undefined,
      fiber_100g: parseFloat(nutriments.fiber_100g) || undefined,
      proteins_100g: parseFloat(nutriments.proteins_100g) || undefined,
      salt_100g: parseFloat(nutriments.salt_100g) || undefined,
      sodium_100g: parseFloat(nutriments.sodium_100g) || undefined
    }
  };
}

// OCR format from GPT (after parsing out code fences)
function normalizeGPT(ocr) {
  if (ocr.choices?.[0]?.message?.content) {
    const raw = ocr.choices[0].message.content
      .replace(/^```json/, '')
      .replace(/^```/, '')
      .replace(/```$/, '')
      .trim();
    try {
      ocr = JSON.parse(raw);
    } catch (e) {
      return { error: "Failed to parse GPT response", details: e.message };
    }
  }

  const nutrition = {};
  const allowedKeys = [
    "energy_kcal", "energy_kj", "fat", "saturated_fat",
    "carbohydrates", "sugars", "fiber", "proteins", "salt", "sodium"
  ];
  for (const key of allowedKeys) {
    if (ocr.nutrition_per_100g?.[key] !== undefined) {
      nutrition[`${key}_100g`] = parseFloat(
        String(ocr.nutrition_per_100g[key]).replace(",", ".")
      );
    }
  }

  return {
    product_name: ocr.product_name || "",
    barcode: ocr.barcode || "",
    category: "",
    nutriscore: "",
    image_url: "",
    image_ingredients_url: "",
    image_nutrition_url: "",
    ingredients_text: ocr.ingredients_text || "",
    ingredients: (ocr.ingredients || []).map(i => ({
      id: i.id?.toLowerCase().trim() || ""
    })),
    allergy_info: ocr.allergy_info || "",
    nutrition_per_100g: nutrition
  };
}

// Route to correct normalizer
const output = isOpenFoodFacts ? normalizeOpenFoodFacts(input) : normalizeGPT(input);

return [{ json: output }];

const profileItem = $items("Profile Manager Agent")[0];
const productItem = $items("Label Normalizer Agent")[0];

if (!profileItem || !productItem) {
  return [{ json: { error: "One of the inputs is missing" } }];
}

return [{
  json: {
    ...productItem.json,
    user_profile: profileItem.json.user_profile || {}
  }
}];

return [{
  json: {
    alternatives: [
      { name: "VeganBar Lite", reason: "No milk or lecithin, only 4g sugar" },
      { name: "Nut-Free Energy Bar", reason: "No peanuts, low sugar, vegan certified" }
    ]
  }
}];

/**
 * data already holds:
 *   score, flags, summary, explained, suggestion, alternatives, coaching_message, …
 */
const data = items[0].json;

/* ── your existing explanation builder ─────────────── */
const userProfile = data.user_profile || {};
const allergies   = new Set((userProfile.allergies || []).map(a => a.toLowerCase()));
const dietSet     = new Set((userProfile.diet      || []).map(d => d.toLowerCase()));
const healthGoals = new Set((userProfile.health_goals || []).map(h => h.toLowerCase()));
const ingredients = new Set((data.ingredients || []).map(i => i.id?.toLowerCase()));

const triggered   = [...allergies].filter(a => ingredients.has(a));
const fat   = data.nutrition_per_100g?.fat           || 0;
const carbs = data.nutrition_per_100g?.carbohydrates || 0;

let explanation = [];
if (triggered.length) explanation.push(`Allergy alert: ${triggered.join(", ")}.`);
if (healthGoals.has("low fat"))
  explanation.push(fat > 20
    ? `High fat content (${fat} g).`
    : `Fat content (${fat} g) is within goal.`);
if (dietSet.has("keto"))
  explanation.push(carbs > 10
    ? `High carbohydrate content (${carbs} g) – not keto.`
    : `Low carbohydrate content (${carbs} g) – keto-friendly.`);

/* ── WRAP for Streamlit ────────────────────────────── */
return [
  {
    json: {
      message: {
        content: {
          ...data,
          score_explanation: explanation.join(" ")
        },
        coaching_message: data.coaching_message || ""
      }
    }
  }
];

