// Extract the raw string from message.content (it's a JSON-like string)
let raw = items[0].json.message?.content || "";

// Strip backticks and trim
raw = raw.trim().replace(/^```(json)?/, "").replace(/```$/, "").trim();

try {
  const parsed = JSON.parse(raw);
  return [{ json: parsed }];
} catch (e) {
  return [{
    json: {
      coaching_message: "⚠️ Could not parse coaching message. Please try again."
    }
  }];
}

// Get analyzer data from item 1, alternatives from item 0
const analyzer = items[1].json.message?.content || {};
const alternatives = items[0].json.alternatives || [];

return [{
  json: {
    ...analyzer,
    alternatives
  }
}];

const base64String = $json.label_photo || "";

return [{
  json: {
    ...$json,
    base64: base64String   // explicitly pass base64 along
  },
  binary: {
    label_photo: {
      data: Buffer.from(base64String, "base64"),
      mimeType: "image/jpeg"
    }
  }
}];

