={
  "model": "gpt-4o",
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "text",
          "text": "You are a food label reader that receives a photo of a food package. The label may be in any language (e.g., Dutch, German, French).\n\nYour job is to extract the following data:\n\n1. `product_name`: from the label.\n\n2. `ingredients_text`: the full printed ingredient list **in the original language**, exactly as on the label.\n\n3. `ingredients`: a standardized array of English ingredient IDs, for example:\n```json\n[{ \"id\": \"whole-wheat-flour\" }, { \"id\": \"salt\" }]\n```\nUse English identifiers where possible (from OpenFoodFacts-style taxonomy). Do not translate brand names or compound terms incorrectly.\n\n4. `nutrition_per_100g`: nutrition values using **English keys** like `fat`, `saturated_fat`, `carbohydrates`, `sugars`, `salt`, `fiber`, `proteins`, `energy_kcal`, `energy_kj`. Convert foreign-language label keys to English field names.\n\n5. `allergy_info`: the full allergen warning text **in the original language**.\n\n⚠️ Return only clean, valid JSON — no comments, markdown, or explanation."
        },
        {
          "type": "image_url",
          "image_url": {
            "url": "data:image/jpeg;base64,{{$json.base64}}"
          }
        }
      ]
    }
  ],
  "max_tokens": 1000
}

parameters.jsCode:
const barcode = $json.barcode ?? '';
const productName = ($json.product_name ?? '').replace(/'/g, "''");
const kcal = $json.nutrition_per_100g?.energy_kcal_100g ?? null;
const ingredientsText = ($json.ingredients_text ?? '').replace(/'/g, "''");
const source = $json.image_url ? "openfoodfacts" : "label_reader";
const timestamp = new Date().toISOString();
const rawJson = JSON.stringify($json).replace(/'/g, "''");

return [{
  json: {
    query: `
      INSERT INTO food_products (
        barcode,
        product_name,
        nutrition_kcal,
        ingredients_text,
        source,
        timestamp,
        raw_json
      )
      VALUES (
        '${barcode}',
        '${productName}',
        ${kcal},
        '${ingredientsText}',
        '${source}',
        '${timestamp}',
        '${rawJson}'
      );
    `
  }
}];
